export {
	type BuildFilterOptions,
	buildFilterWhere,
	type ColumnMapping,
	type ParameterizedSql,
	type PlaceholderStyle,
	type SqlDialect,
} from "./filter-sql.ts";

/**
 * Filter → parameterized `WHERE` builder.
 *
 * Dialects: `postgres` (default, preserves historical output), `sqlite`,
 * `mysql`. Case-insensitive matching is the default (`ILIKE` on Postgres,
 * `LOWER(col) LIKE LOWER(?)` elsewhere); pass `caseSensitive: true` for
 * binary `LIKE`.
 *
 * Historical `include` / `exclude` short names are normalized to
 * `includeAll` / `excludeAll` at the serialization boundary
 * (`deserializeFilters`) and defensively here, so the operator table only
 * carries canonical names. `includeAny` / `excludeAny` use overlap (`&&`).
 */

import type { ColumnConfig } from "../columns.ts";
import { isSearchColumnId } from "../columns.ts";
import { DataExplorerError } from "../errors.ts";
import { groupConditions } from "../features/data-filtering/filter-grouping.ts";
import { validateCondition } from "../features/data-filtering/filter-semantics.ts";
import { normalizeOperator } from "../features/data-filtering/operators.ts";
import type {
	FilterCondition,
	FilterGroup,
	FilterOperator,
} from "../filters.ts";
import { isFilterGroup } from "../filters.ts";
import { escapeLikePattern, quotePgIdent } from "./pg-identifiers.ts";

export interface ParameterizedSql {
	params: unknown[];
	sql: string;
}

export type ColumnMapping = Record<string, string>;

/** SQL dialect for generated predicates. Default `postgres` (historical output). */
export type SqlDialect = "postgres" | "sqlite" | "mysql";

export type PlaceholderStyle = "numbered" | "positional";

export interface BuildFilterOptions {
	/** `false` → `ILIKE` / `LOWER(col) LIKE`. @default false */
	caseSensitive?: boolean;
	/** @default "postgres" */
	dialect?: SqlDialect;
	/**
	 * Placeholder rendering. Defaults per dialect (`numbered` for postgres,
	 * `positional` for sqlite/mysql) — pass explicitly for cross-dialect codegen.
	 */
	placeholderStyle?: PlaceholderStyle;
	tableAlias?: string;
}

function mysqlQuote(name: string): string {
	return `\`${name.replace(/`/g, "``")}\``;
}

function quoteIdent(name: string, dialect: SqlDialect): string {
	return dialect === "mysql" ? mysqlQuote(name) : quotePgIdent(name);
}

function buildLike(
	col: string,
	param: string,
	not: boolean,
	dialect: SqlDialect,
	caseSensitive: boolean,
): string {
	const ilike = dialect === "postgres" && !caseSensitive ? "ILIKE" : "LIKE";
	const keyword = not ? `NOT ${ilike}` : ilike;
	if (!caseSensitive && dialect !== "postgres") {
		return `LOWER(${col}) ${keyword} LOWER(${param}) ESCAPE '\\'`;
	}
	return `${col} ${keyword} ${param} ESCAPE '\\'`;
}

function assertArraySupported(operator: string, dialect: SqlDialect): void {
	if (dialect !== "postgres") {
		throw new DataExplorerError(
			"UNSUPPORTED_DIALECT",
			`Operator "${operator}" needs Postgres text[] containment; no equivalent exists for dialect "${dialect}".`,
			{ dialect, operator },
		);
	}
}

interface BuildContext {
	caseSensitive: boolean;
	columnMap: Map<string, ColumnConfig>;
	dialect: SqlDialect;
	nextIdx: number;
	params: unknown[];
	placeholderStyle: PlaceholderStyle;
	searchableCols: ColumnConfig[];
}

function pushParam(ctx: BuildContext, value: unknown): string {
	ctx.params.push(value);
	return ctx.placeholderStyle === "positional" ? "?" : `$${ctx.nextIdx++}`;
}

function colRef(
	columnName: string,
	tableAlias: string | undefined,
	dialect: SqlDialect,
): string {
	const quoted = quoteIdent(columnName, dialect);
	return tableAlias ? `${quoteIdent(tableAlias, dialect)}.${quoted}` : quoted;
}

/** Single validation entry point with explicit matchable codes (see `validateCondition`). */
function validateConditions(
	conditions: FilterCondition[],
	columnMap: Map<string, ColumnConfig>,
): void {
	for (const cond of conditions) {
		const error = validateCondition(cond, columnMap);
		if (error) {
			throw new DataExplorerError(error.code, error.message, error.details);
		}
	}
}

type SqlBuilder = (
	col: string,
	cond: FilterCondition,
	ctx: BuildContext,
) => string;

/**
 * Single post-validation invariant for builder payloads. `validateCondition`
 * already gates `buildFilterWhere`, so these only guard against direct
 * internal misuse — one helper instead of three bespoke asserts with
 * duplicated messages.
 */
function assertValue(
	cond: FilterCondition,
	predicate: (value: unknown) => boolean,
	expected: string,
): void {
	if (!predicate(cond.value)) {
		throw new DataExplorerError(
			"INVALID_FILTER_VALUE",
			`Invalid filter condition: Operator "${cond.operator}" ${expected}`,
			{ columnId: cond.columnId, operator: cond.operator },
		);
	}
}

function isArrayValue(value: unknown): value is unknown[] {
	return Array.isArray(value);
}

function isStringValue(value: unknown): value is string {
	return typeof value === "string";
}

function isRangeValue(value: unknown): value is [unknown, unknown] {
	return Array.isArray(value) && value.length === 2;
}

function arrayOp(
	col: string,
	cond: FilterCondition,
	ctx: BuildContext,
	op: "@>" | "&&",
): string {
	assertArraySupported(cond.operator, ctx.dialect);
	assertValue(cond, isArrayValue, "requires string[] value");
	const values = cond.value as unknown[];
	// Postgres text[] containment/overlap.
	return `${col} ${op} ARRAY[${values.map((v) => pushParam(ctx, v)).join(", ")}]::text[]`;
}

function notArrayOp(
	col: string,
	cond: FilterCondition,
	ctx: BuildContext,
	op: "@>" | "&&",
): string {
	return `NOT (${arrayOp(col, cond, ctx, op)})`;
}

function betweenOp(
	col: string,
	cond: FilterCondition,
	ctx: BuildContext,
	not: boolean,
): string {
	assertValue(cond, isRangeValue, "requires [min, max] tuple");
	const [min, max] = cond.value as [unknown, unknown];
	const keyword = not ? "NOT BETWEEN" : "BETWEEN";
	return `${col} ${keyword} ${pushParam(ctx, min)} AND ${pushParam(ctx, max)}`;
}

function likeOp(
	col: string,
	cond: FilterCondition,
	ctx: BuildContext,
	pattern: (v: string) => string,
	not: boolean,
): string {
	assertValue(cond, isStringValue, "requires a non-null value");
	const value = cond.value as string;
	const param = pushParam(ctx, pattern(escapeLikePattern(value)));
	return buildLike(col, param, not, ctx.dialect, ctx.caseSensitive);
}

function comparisonBuilder(op: string): SqlBuilder {
	return (col, cond, ctx) => `${col} ${op} ${pushParam(ctx, cond.value)}`;
}

type NonNullaryOperator = Exclude<FilterOperator, "isEmpty" | "isNotEmpty">;

const OPERATOR_SQL_BUILDERS: Record<NonNullaryOperator, SqlBuilder> = {
	between: (col, cond, ctx) => betweenOp(col, cond, ctx, false),
	contains: (col, cond, ctx) => likeOp(col, cond, ctx, (v) => `%${v}%`, false),
	endsWith: (col, cond, ctx) => likeOp(col, cond, ctx, (v) => `%${v}`, false),
	eq: comparisonBuilder("="),
	excludeAll: (col, cond, ctx) => notArrayOp(col, cond, ctx, "@>"),
	excludeAny: (col, cond, ctx) => notArrayOp(col, cond, ctx, "&&"),
	gt: comparisonBuilder(">"),
	gte: comparisonBuilder(">="),
	in: (col, cond, ctx) => {
		assertValue(cond, isArrayValue, "requires string[] value");
		const values = cond.value as unknown[];
		if (values.length === 0) return "(1=0)";
		return `${col} IN (${values.map((v) => pushParam(ctx, v)).join(", ")})`;
	},
	includeAll: (col, cond, ctx) => arrayOp(col, cond, ctx, "@>"),
	includeAny: (col, cond, ctx) => arrayOp(col, cond, ctx, "&&"),
	lt: comparisonBuilder("<"),
	lte: comparisonBuilder("<="),
	neq: comparisonBuilder("!="),
	notBetween: (col, cond, ctx) => betweenOp(col, cond, ctx, true),
	notContains: (col, cond, ctx) =>
		likeOp(col, cond, ctx, (v) => `%${v}%`, true),
	notIn: (col, cond, ctx) => {
		assertValue(cond, isArrayValue, "requires string[] value");
		const values = cond.value as unknown[];
		if (values.length === 0) return "(1=1)";
		return `${col} NOT IN (${values.map((v) => pushParam(ctx, v)).join(", ")})`;
	},
	startsWith: (col, cond, ctx) => likeOp(col, cond, ctx, (v) => `${v}%`, false),
};

function isEmptySql(
	col: string,
	type: ColumnConfig["type"] | undefined,
): string {
	// Empty strings read as empty for text; other types only match NULL.
	if (type === "string") return `(${col} IS NULL OR ${col} = '')`;
	return `${col} IS NULL`;
}

function buildConditionSql(
	condition: FilterCondition,
	columnMapping: ColumnMapping,
	ctx: BuildContext,
	tableAlias: string | undefined,
): string {
	if (isSearchColumnId(condition.columnId)) {
		assertValue(condition, isStringValue, "requires a non-null value");
		return buildSearchSql(
			condition.value as string,
			columnMapping,
			ctx,
			tableAlias,
		);
	}

	const columnName = columnMapping[condition.columnId];
	if (!columnName) {
		throw new DataExplorerError(
			"MISSING_MAPPING",
			`Missing column mapping for "${condition.columnId}"`,
			{ columnId: condition.columnId },
		);
	}

	const col = colRef(columnName, tableAlias, ctx.dialect);

	if (condition.operator === "isEmpty" || condition.operator === "isNotEmpty") {
		const type = ctx.columnMap.get(condition.columnId)?.type;
		if (condition.operator === "isEmpty") return isEmptySql(col, type);
		return type === "string"
			? `(${col} IS NOT NULL AND ${col} != '')`
			: `${col} IS NOT NULL`;
	}

	// `validateConditions` already normalized aliases and rejected nullary
	// operators here, so the lookup is a direct table hit.
	const canonical = normalizeOperator(condition.operator);
	const builder: SqlBuilder | undefined =
		canonical === undefined
			? undefined
			: OPERATOR_SQL_BUILDERS[canonical as NonNullaryOperator];
	if (!builder) {
		throw new DataExplorerError(
			"INVALID_OPERATOR",
			`Unhandled filter operator: ${condition.operator}`,
			{ columnId: condition.columnId, operator: condition.operator },
		);
	}

	return builder(col, condition, ctx);
}

function buildSearchSql(
	searchTerm: string,
	columnMapping: ColumnMapping,
	ctx: BuildContext,
	tableAlias: string | undefined,
): string {
	const searchableCols = ctx.searchableCols;

	if (searchableCols.length === 0) {
		throw new DataExplorerError(
			"NO_SEARCHABLE_COLUMN",
			"Search filter requires at least one searchable column",
		);
	}

	// Reuse the regular `contains` path per column so mapping, quoting, and
	// LIKE rendering stay in one place. Synthetic conditions can't recurse:
	// their `columnId` is never `_search`.
	const conditions = searchableCols.map((colConfig) =>
		buildConditionSql(
			{
				columnId: colConfig.id,
				combinator: "and",
				id: `search-${colConfig.id}`,
				operator: "contains",
				value: searchTerm,
			},
			columnMapping,
			ctx,
			tableAlias,
		),
	);

	return conditions.length === 1
		? (conditions[0] as string)
		: `(${conditions.join(" OR ")})`;
}

function buildGroupSql(
	group: FilterGroup,
	columnMapping: ColumnMapping,
	ctx: BuildContext,
	tableAlias: string | undefined,
): string {
	const sqls: string[] = [];

	for (const item of group.conditions) {
		const sub = isFilterGroup(item)
			? buildGroupSql(item, columnMapping, ctx, tableAlias)
			: buildConditionSql(item, columnMapping, ctx, tableAlias);
		sqls.push(sub);
	}

	if (sqls.length === 0) {
		throw new DataExplorerError("EMPTY_GROUP", "Empty filter group");
	}
	if (sqls.length === 1) return sqls[0] as string;

	const joiner = group.combinator === "or" ? " OR " : " AND ";
	return `(${sqls.join(joiner)})`;
}

/**
 * Build a parameterized `WHERE` fragment.
 *
 * Always returns a result — empty filters yield `{ sql: "", params: [] }`
 * (no `undefined` branching at call sites).
 *
 * @example
 * ```ts
 * // Postgres (default)
 * buildFilterWhere(filters, columns, mapping, { tableAlias: "tasks" });
 * // SQLite
 * buildFilterWhere(filters, columns, mapping, { dialect: "sqlite" });
 * ```
 */
export function buildFilterWhere(
	conditions: FilterCondition[],
	columnsConfig: ColumnConfig[],
	columnMapping: ColumnMapping,
	options?: BuildFilterOptions,
): ParameterizedSql {
	const {
		tableAlias,
		dialect = "postgres",
		caseSensitive = false,
		placeholderStyle = dialect === "postgres" ? "numbered" : "positional",
	} = options ?? {};
	const columnMap = new Map(columnsConfig.map((c) => [c.id, c]));
	validateConditions(conditions, columnMap);
	if (conditions.length === 0) return { params: [], sql: "" };

	const group = groupConditions(conditions);

	const ctx: BuildContext = {
		caseSensitive,
		columnMap,
		dialect,
		nextIdx: 1,
		params: [],
		placeholderStyle,
		searchableCols: columnsConfig.filter(
			(c) => c.searchable && !isSearchColumnId(c.id),
		),
	};

	const sql = buildGroupSql(group, columnMapping, ctx, tableAlias);

	return { params: [...ctx.params], sql };
}

/**
 * Server-safe surface of `@adistack/data-explorer/backend`.
 *
 * Postgres-only filter → SQL construction for Bun/server bundles: the
 * transitive in-package import closure is React / TanStack / zod free
 * (enforced by `./no-ui-imports.test.ts`, not by review). Explicit
 * allow-list, no `export *`.
 *
 * Deliberately excluded: `SqlDialect` / `PlaceholderStyle` /
 * `BuildFilterOptions` (root-compat only — pg is pinned here, unsupported
 * configurations are compile-time errors, not runtime throws);
 * `filter-condition-schema.ts` (zod — server consumers must not pull it);
 * `filter-utils.ts` serialization, hooks, provider, context, views,
 * query keys, display snapshots (client concerns); `createFilter` and the
 * rest of `filter-draft.ts` (nanoid authoring is UI-side — only the pure
 * `createSearchFilter` helper is exposed below).
 */

// --- Columns (../columns.ts) ---
export {
	type ColumnConfig,
	type ColumnDataType,
	isSearchColumnId,
	SEARCH_COLUMN_ID,
} from "../columns.ts";
// --- Errors (subset: NO MissingProviderError — UI-only) ---
export { DataExplorerError, type DataExplorerErrorCode } from "../errors.ts";
// --- Search draft (../features/data-filtering/filter-draft.ts): imports are
// pure (columns/filters/filter-semantics/operators + nanoid only), verified
// by the import-graph test. ---
export { createSearchFilter } from "../features/data-filtering/filter-draft.ts";
// --- Grouping ---
export { groupConditions } from "../features/data-filtering/filter-grouping.ts";
// --- Semantics (filter-semantics.ts: validation Aspen reuses pre-build) ---
export {
	type CoercedFilterValue,
	type ConditionValidationError,
	coerceFilterValue,
	validateCondition,
	validateFilterValue,
} from "../features/data-filtering/filter-semantics.ts";
// --- Operators (../features/data-filtering/operators.ts) ---
export {
	FILTER_OPERATORS,
	getDefaultOperator,
	getOperatorArity,
	getOperatorLabel,
	getOperatorsForType,
	normalizeOperator,
	type OperatorArity,
} from "../features/data-filtering/operators.ts";
// --- Filters (../filters.ts: predicates + FilterGroup) ---
export {
	type FilterCondition,
	type FilterGroup,
	type FilterOperator,
	hasFilters,
	isFilterGroup,
	type SerializedFilterCondition,
	type TypedFilterValue,
} from "../filters.ts";
// --- Shared SQL types (from ./index.ts — NO dialect/placeholder types) ---
export type { ColumnMapping, ParameterizedSql } from "./index.ts";
// --- Postgres identifiers (./pg-identifiers.ts) ---
export { escapeLikePattern, pgColRef, quotePgIdent } from "./pg-identifiers.ts";
// --- Postgres WHERE (./pg-where.ts) ---
export { type BuildPgWhereOptions, buildFilterWherePg } from "./pg-where.ts";

import type { ColumnConfig } from "../columns.ts";
import type { FilterCondition } from "../filters.ts";
import type { ColumnMapping, ParameterizedSql } from "./index.ts";
import { buildFilterWhere } from "./index.ts";

export interface BuildPgWhereOptions {
	/** `true` → binary `LIKE`; default `false` → `ILIKE`. Only pg semantic kept. */
	caseSensitive?: boolean;
	tableAlias?: string;
}

/**
 * Postgres-only `buildFilterWhere`: `$n` numbered placeholders, always.
 *
 * Wrapper (not fork) over the shared builder, so parity with the root
 * `buildFilterWhere({ dialect: "postgres" })` is structural; the
 * `./pg-where.test.ts` matrix locks it test-by-test.
 */
export function buildFilterWherePg(
	conditions: FilterCondition[],
	columnsConfig: ColumnConfig[],
	columnMapping: ColumnMapping,
	options?: BuildPgWhereOptions,
): ParameterizedSql {
	return buildFilterWhere(conditions, columnsConfig, columnMapping, {
		caseSensitive: options?.caseSensitive ?? false,
		dialect: "postgres",
		placeholderStyle: "numbered",
		tableAlias: options?.tableAlias,
	});
}

/**
 * Postgres identifier quoting + LIKE escaping — single home for these
 * helpers, shared by the multi-dialect builder (`./filter-sql.ts`) and
 * the Postgres-pinned `backend` entry. Zero imports, so the backend
 * closure stays React-free (`./no-ui-imports.test.ts` guards this)
 * and callers can compose identifiers without pulling the builder.
 */

/** Quote a Postgres identifier: `name` → `"name"`, embedded `"` doubled. */
export function quotePgIdent(name: string): string {
	return `"${name.replace(/"/g, '""')}"`;
}

/** `col` → `"col"`; with alias → `"alias"."col"`. */
export function pgColRef(columnName: string, tableAlias?: string): string {
	return tableAlias
		? `${quotePgIdent(tableAlias)}.${quotePgIdent(columnName)}`
		: quotePgIdent(columnName);
}

/** Escape LIKE wildcards so user input matches literally (`\`, `%`, `_`). */
export function escapeLikePattern(value: string): string {
	return value.replace(/\\/g, "\\\\").replace(/%/g, "\\%").replace(/_/g, "\\_");
}

/**
 * Matchable error taxonomy for `@adistack/data-explorer`.
 *
 * Every throw in the headless core uses {@link DataExplorerError} (or a
 * subclass) with a stable {@link DataExplorerErrorCode} so consumers can
 * branch on `error.code` instead of regex-matching `error.message`.
 * Plain `Error` and `console.*` are never used from library code.
 *
 * @example
 * ```ts
 * import { DataExplorerError, buildFilterWhere } from "@adistack/data-explorer";
 *
 * try {
 *   buildFilterWhere(filters, columns, mapping);
 * } catch (error) {
 *   if (error instanceof DataExplorerError && error.code === "UNKNOWN_COLUMN") {
 *     highlightChip(error.details?.["columnId"] as string);
 *   }
 * }
 * ```
 */

/** Stable codes for every failure the headless core can raise. */
export type DataExplorerErrorCode =
	| "MISSING_QUERY_CLIENT"
	| "INVALID_QUERY_OPTIONS"
	| "UNKNOWN_COLUMN"
	| "MISSING_MAPPING"
	| "INVALID_OPERATOR"
	| "INVALID_FILTER_VALUE"
	| "INVALID_FILTER_JSON"
	| "EMPTY_GROUP"
	| "NO_SEARCHABLE_COLUMN"
	| "UNSUPPORTED_DIALECT"
	| "INVALID_COLUMN_DEF"
	| "UNKNOWN_VIEW"
	| "VIEWS_NOT_CONFIGURED"
	| "MISSING_PROVIDER";

/** Base error for the data-explorer core. Branch on {@link code}. */
export class DataExplorerError extends Error {
	/** Stable machine-readable failure code. */
	readonly code: DataExplorerErrorCode;
	/** Structured context (e.g. `{ columnId }`) for UI highlighting. */
	readonly details?: Record<string, unknown>;

	constructor(
		code: DataExplorerErrorCode,
		message: string,
		details?: Record<string, unknown>,
	) {
		super(message);
		this.name = "DataExplorerError";
		this.code = code;
		if (details !== undefined) this.details = details;
	}
}

/**
 * Thrown when a context hook runs outside `<Provider>`.
 * Includes the hook name so copy-pasted `useSelectionContext` failures
 * point at the right call site.
 */
export class MissingProviderError extends DataExplorerError {
	constructor(hookName = "useDataExplorerContext") {
		super(
			"MISSING_PROVIDER",
			`${hookName} must be used within <Provider> (did you forget DataExplorerProvider / QueryClientProvider?).`,
			{ hookName },
		);
		this.name = "MissingProviderError";
	}
}
